\begin{document}

	\pagestyle{empty}
	\definecolor{deepskyblue}{rgb}{0.173,0.447,0.682}
	\definecolor{orangepeel}{rgb}{0.902, 0.624, 0}
	\definecolor{lightyellow}{rgb}{0.953,0.882,0.388}
	\definecolor{darkgreen}{rgb}{0.271, 0.608, 0.463}
	\definecolor{lightblue}{rgb}{0.484,0.702,0.894}
	\definecolor{rustred}{rgb}{0.784,0.392,0.149}
	\definecolor{fadedpink}{rgb}{0.753,0.494,0.643}

	\begin{tikzpicture}[
	->, >= latex, shorten >= 1pt, node distance=2cm, thick,
	main node/.style = {circle, draw, minimum size=6mm},
	loop/.style = {looseness=20}
	]


% Draw the digraphs
\begin{scope} 	

% Nodes
\node[main node, draw=deepskyblue!80, fill=deepskyblue!20, label=center:{$1$}] (1) {};
\node[main node, draw=deepskyblue!80, fill=deepskyblue!20,  label=center:{$2$}] (2) [below left of = 1] {};
\node[main node, draw=deepskyblue!80, fill=deepskyblue!20,  label=center:{$3$}] (3) [below right of = 1] {};

% Arrows
\path
(2) edge [loop below] (2)
(3) edge [loop below] (3)
;

\node[] at (0,-3) {\Large I};
\end{scope}

\begin{scope}[shift={(4.5,0)}]

% Nodes
\node[main node, draw=deepskyblue!80, fill=deepskyblue!20,  label=center:{$1$}] (1) {};
\node[main node, draw=deepskyblue!80, fill=deepskyblue!20,  label=center:{$2$}] (2) [below left of = 1] {};
\node[main node, draw=deepskyblue!80, fill=deepskyblue!20,  label=center:{$3$}] (3) [below right of = 1] {};

% Arrows
\path
(2) edge (1)
(1) edge [bend right] (2)

(1) edge (3)
(3) edge [bend right] (1)
;

\node[] at (0,-3) {\Large II};
\end{scope}

\begin{scope}[shift={(9,0)}]

% Nodes
\node[main node, draw=deepskyblue!80, fill=deepskyblue!20,  label=center:{$1$}] (1) {};
\node[main node, draw=deepskyblue!80, fill=deepskyblue!20,  label=center:{$2$}] (2) [below left of = 1] {};
\node[main node, draw=deepskyblue!80, fill=deepskyblue!20,  label=center:{$3$}] (3) [below right of = 1] {};

% Arrows
\path
(1) edge (2)
(2) edge (3)
(3) edge (1)
;
\node[] at (0,-3) {\Large III};
\end{scope}

\end{tikzpicture}
\end{document}
